(function(){
  function rand(a,b){return a+Math.random()*(b-a);}
  const N = 90;
  let particles = [];
  function initParticles(){
    particles = [];
    for(let i=0;i<N;i++){
      let x,y,tries=0;
      do{
        x = rand(0,W());
        y = rand(0,H());
        tries++;
      } while(tries<8 && Math.hypot(x-W()/2,y-H()/2) < Math.min(W(),H())*0.22 && Math.random()<0.85);
      particles.push({
        x:x, y:y,
        r: rand(4,22),
        baseAlpha: rand(0.15,0.55),
        phase: rand(0,Math.PI*2),
        speed: rand(0.15,0.4),
        drift: rand(-0.3,0.3),
        colorIdx: Math.floor(Math.random()*PALETTE.length)
      });
    }
  }
  initParticles();

  function buildingsData(){
    let arr=[];
    let n=6;
    for(let i=0;i<n;i++){
      arr.push({ w: rand(30,70), h: rand(80,260) });
    }
    return arr;
  }
  const leftB = buildingsData();
  const rightB = buildingsData();

  function drawBuildings(arr, side, time){
    let x = side==='l' ? -10 : W()+10;
    for(let i=0;i<arr.length;i++){
      const b = arr[i];
      const bw = b.w, bh = b.h;
      let bx = side==='l' ? x : x - bw;
      const by = H() - bh;
      ctx.fillStyle = 'rgba(58,42,74,0.35)';
      ctx.fillRect(bx, by, bw, bh);
      const rows = Math.max(2, Math.floor(bh/28));
      const cols = Math.max(1, Math.floor(bw/18));
      for(let r=0;r<rows;r++){
        for(let c=0;c<cols;c++){
          const wx = bx + 6 + c*(bw-12)/cols;
          const wy = by + 10 + r*(bh-20)/rows;
          const flick = 0.4 + 0.6*Math.abs(Math.sin(time*0.0006 + i*2+r*3+c));
          ctx.fillStyle = 'rgba(244,217,160,'+(0.25*flick)+')';
          ctx.fillRect(wx, wy, 6, 8);
        }
      }
      x = side==='l' ? x + bw + rand(4,14) : x - bw - rand(4,14);
    }
  }

  function frame(time){
    ctx.clearRect(0,0,W(),H());
    const w = W(), h = H();

    const gradL = ctx.createRadialGradient(0,h,10,0,h,w*0.5);
    gradL.addColorStop(0,'rgba(232,161,92,0.18)');
    gradL.addColorStop(1,'rgba(232,161,92,0)');
    ctx.fillStyle = gradL;
    ctx.fillRect(0,0,w,h);

    const gradR = ctx.createRadialGradient(w,h,10,w,h,w*0.5);
    gradR.addColorStop(0,'rgba(232,161,92,0.18)');
    gradR.addColorStop(1,'rgba(232,161,92,0)');
    ctx.fillStyle = gradR;
    ctx.fillRect(0,0,w,h);

    drawBuildings(leftB,'l',time);
    drawBuildings(rightB,'r',time);

    for(let p of particles){
      p.y -= p.speed*0.5;
      p.x += Math.sin(time*0.0003+p.phase)*p.drift*0.3;
      if(p.y < -30){ p.y = h+30; p.x = rand(0,w); }
      const alpha = p.baseAlpha*(0.6+0.4*Math.sin(time*0.001+p.phase));
      const col = PALETTE[p.colorIdx % PALETTE.length];
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.shadowBlur = p.r*1.5;
      ctx.shadowColor = col;
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
      ctx.fill();
      ctx.restore();
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
